272→            input.setAttribute('aria-invalid', 'true');
273→            errorDiv.textContent = message;
274→            errorDiv.classList.add('visible');
275→        }
276→
277→        function clearError(input) {
278→            const errorDiv = document.getElementById(input.id + '-error');
279→            input.classList.remove('error');
280→            input.removeAttribute('aria-invalid');
281→            errorDiv.textContent = '';
282→            errorDiv.classList.remove('visible');
283→        }
284→
285→        function validateEmail(email) {
286→            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
287→        }
288→
289→        form.addEventListener('submit', async (e) => {
290→            e.preventDefault();
291→            
292→            // Clear previous errors
293→            clearError(emailInput);
294→            clearError(passwordInput);
295→
296→            let hasError = false;
297→
298→            if (!emailInput.value) {
299→                showError(emailInput, '请输入电子邮箱地址');
300→                hasError = true;
301→            } else if (!validateEmail(emailInput.value)) {
302→                showError(emailInput, '请输入有效的电子邮箱地址');
303→                hasError = true;
304→            }
305→
306→            if (!passwordInput.value) {
307→                showError(passwordInput, '请输入密码');
308→                hasError = true;
309→            }
310→
311→            if (hasError) {
312→                // Focus first error field
313→                const firstError = form.querySelector('[aria-invalid="true"]');
314→                if (firstError) firstError.focus();
315→                return;
316→            }
317→
318→            // Simulate login request
319→            submitBtn.disabled = true;
320→            submitBtn.classList.add('loading');
321→            submitBtn.setAttribute('aria-busy', 'true');
322→
323→            try {
324→                await new Promise(resolve => setTimeout(resolve, 2000));
325→                // Success handling would go here
326→                alert('登录成功！');
327→            } catch (error) {
328→                showError(emailInput, '登录失败，请重试');
329→            } finally {
330→                submitBtn.disabled = false;
331→                submitBtn.classList.remove('loading');
332→                submitBtn.removeAttribute('aria-busy');
333→            }
334→        });
335→
336→        // Real-time validation clearing
337→        emailInput.addEventListener('input', () => {
338→            if (emailInput.classList.contains('error')) clearError(emailInput);
339→        });
340→
341→        passwordInput.addEventListener('input', () => {
342→            if (passwordInput.classList.contains('error')) clearError(passwordInput);
343→        });
344→    </script>
